function privatePhoneCloudSchedule(delay){if(!privatePhoneAccountAvailable()||_privatePhoneCloudTimer)return;_privatePhoneCloudTimer=setTimeout(()=>{_privatePhoneCloudTimer=null;privatePhoneCloudAutoBackup();},Math.max(1000,+delay||PRIVATE_PHONE_AUTO_BACKUP_DELAY));}
