async function privatePhoneCloudAutoBackup(){if(!privatePhoneAccountAvailable()||_privatePhoneCloudBusy||!_privatePhoneCloudDirtyAt)return;if(northNativeMaintenancePaused()||typeof document!=='undefined'&&document.hidden||Date.now()-_privatePhoneLastInteractionAt<90000||typeof replyGenerationStore==='function'&&Object.keys(replyGenerationStore()).length||typeof _momentReplyBusy!=='undefined'&&_momentReplyBusy.size){privatePhoneCloudSchedule(PRIVATE_PHONE_AUTO_BACKUP_RETRY);return;}try{if(!_privatePhoneAccount.loaded)await privatePhoneAccountRefresh(false);if(!_privatePhoneAccount.loggedIn)return;const info=await privatePhoneAccountCall('account.backup.info');if(!info||info.ok===false)return;const cloudAt=info.found?Date.parse(info.backup&&info.backup.captured_at||'')||0:0,mirrorReady=!cloudUrl()||!cloudKey()||(+((S.settings||{}).privateMirrorLastUploadedAt)||0)>=_privatePhoneCloudDirtyAt;if(cloudAt>=_privatePhoneCloudDirtyAt&&mirrorReady){_privatePhoneCloudDirtyAt=0;return;}await privatePhoneCloudBackup(false,true);}catch(_){privatePhoneCloudSchedule(PRIVATE_PHONE_AUTO_BACKUP_RETRY);}}
