async function privatePhoneCloudBackup(firstBind,silent){if(!privatePhoneAccountAvailable()||_privatePhoneCloudBusy)return;_privatePhoneCloudBusy=true;if(!silent)toast(firstBind?'正在建立第一份云备份…':'正在备份到手机号账号…');try{if(!await saveNowAsync())throw new Error('本机数据尚未保存完成');const snapshot=await fullBackupState();snapshot._persistedAt=Math.max(+snapshot._persistedAt||0,Date.now());const build=String(window.__SMALL_PHONE_PRIVATE_BUILD__||APP_VER),r=await privatePhoneAccountBackupUpload(snapshot,{capturedAt:snapshot._persistedAt,sourceBuild:build,source:'private-ios',revision:+(S.settings&&S.settings.privateMirrorRevision)||0});if(!r||r.ok!==true)throw new Error(r&&r.message||'云备份上传失败');const mirror=await privatePrimaryMirrorUpload(snapshot);_privatePhoneCloudDirtyAt=0;if(!silent)toast(firstBind?'手机号已绑定，当前数据已安全备份'+(mirror&&mirror.uploaded?'，网页版镜像已更新':''):'云备份已更新'+(mirror&&mirror.uploaded?'，网页版镜像已同步':''));_privatePhoneAccount.loaded=false;await privatePhoneAccountRefresh(false);}catch(e){if(!silent)toast((e&&e.message)||'云备份失败，请稍后重试');}finally{_privatePhoneCloudBusy=false;}}
