function healthPrivate(){return typeof privateNativeAppOn==='function'&&privateNativeAppOn();}
function healthApplies(item){return !item.only||(item.only==='private')===healthPrivate();}
function healthClock(ts,withDate){const d=new Date(+ts||Date.now()),p=n=>String(n).padStart(2,'0');return (withDate?d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+' ':'')+p(d.getHours())+':'+p(d.getMinutes());}
function healthSecs(ms){return (Math.max(0,+ms||0)/1000).toFixed(1)+' 秒';}
function healthAgo(ts){const t=+ts||Date.parse(ts)||0;if(!t)return'时间未知';const m=Math.round((Date.now()-t)/60000);return m<1?'刚刚':m<60?m+' 分钟前':m<1440?Math.round(m/60)+' 小时前':Math.round(m/1440)+' 天前';}
