function healthErr(e){const timed=!!(e&&e.transportTimedOut),name=String(e&&e.name||''),msg=String(e&&e.message||e||'');if(timed||/abort/i.test(name+msg))return (e&&e.transportTimeoutMs?Math.round(e.transportTimeoutMs/1000):'')+' 秒没有回应，请求超时（'+(msg||name||'aborted').slice(0,80)+'）';if(/Load failed|Failed to fetch|NetworkError|network/i.test(msg))return '连不上服务器（'+msg.slice(0,80)+'）：网络断了，或这个网站在当前网络下打不开';return typeof apiCaughtCN==='function'?apiCaughtCN(e):msg.slice(0,160);}
