function healthRouteName(i){return typeof CHAT_ROUTE_NAMES!=='undefined'&&CHAT_ROUTE_NAMES[i]||('路线'+(i+1));}
function healthChatCfg(aux){const i=Math.max(0,parseInt(S.settings&&S.settings.chatRouteActive,10)||0),route=typeof chatRequestRoute==='function'?chatRequestRoute(i):null,main=route||S.settings.chat||{},a=aux?(route?route.aux:S.settings.aux)||{}:main;return{index:i,base:String(a.base||main.base||'').replace(/\/+$/,''),key:String(a.key||main.key||''),model:String(a.model||''),streaming:typeof a.streaming==='boolean'?a.streaming:S.settings.chatStreaming===true,reasoningEnabled:main.reasoningEnabled===true,reasoningEffort:main.reasoningEffort,name:healthRouteName(i)};}
