  async glass(){/* HOME_GLASS_HEALTH_RECOVERY_V1 */const health=typeof _lg!=='undefined'&&_lg.homeHealth;const rows=typeof lgDiagRows==='function'?lgDiagRows():[],recent=rows.filter(r=>Date.now()-(+r.at||0)<7*86400000);if(health&&health.pending)return{state:'skip',sub:'主屏玻璃正在恢复，尚未确认'};if(!recent.length&&!health)return{state:'skip',sub:'当前没有新鲜的主屏绘制结果',fix:'返回主屏后复查；历史成功不能证明当前显示正常。'};if(health&&health.ok&&(!recent.length||health.at>Math.max(...recent.map(r=>+r.at||0))))return{state:'ok',sub:'最近一次绘制已恢复'+(recent.length?' · 七天内有 '+recent.length+' 条历史异常':'' )};if(!recent.length)return{state:'ok',sub:'最近 7 天主屏玻璃没有画失败'};const last=recent.slice(-5).reverse().map(r=>(typeof fmtDT==='function'?fmtDT(r.at):String(r.at))+'：'+r.detail).join('\n');return{state:'warn',sub:'七天内有 '+recent.length+' 条异常记录，尚未确认恢复',why:'最近几次：\n'+last,fix:'返回主屏后会尝试重新绘制；历史记录不代表现在仍有黑块。若仍异常，请保留这页诊断。'};},
  async files(){const scripts=[...document.querySelectorAll('script[src]')].map(s=>String(s.getAttribute('src')||'').split('?')[0]).filter(src=>src&&!/^(?:https?:)?\/\//i.test(src)),missing=[],unknown=[];for(const src of scripts){const mark=HEALTH_SCRIPT_MARKS[src];if(!mark){unknown.push(src);continue;}let ok=false;try{ok=mark.indexOf('shop:')===0?(window.NorthBuiltinShops||[]).some(s=>s&&s.name===mark.slice(5)):Function('return typeof '+mark)()!=='undefined';}catch(_){ok=false;}if(!ok)missing.push(src);}const ver=(typeof APP_VER!=='undefined'?String(APP_VER).split(' ')[0]:'')+(healthPrivate()?' · 私人安装包 '+String(window.__SMALL_PHONE_PRIVATE_BUILD__||'未识别'):' · 网页版');if(missing.length)return{state:'bad',sub:ver+' · '+(scripts.length-missing.length)+'/'+scripts.length+' 个附属文件已加载',why:'这些文件没有加载成功：'+missing.join('、')+'。用到它们的功能会出错（以前的「XX is not defined」就是这样来的）。',fix:healthPrivate()?'彻底划掉小手机再打开；还不行就重新安装这一版。':'等网络好的时候彻底关掉网页再打开；在主屏幕打开的，先划掉再进。'};return{state:'ok',sub:ver+' · '+scripts.length+' 个附属文件都已加载'+(unknown.length?'（其中 '+unknown.length+' 个没有登记检查方法）':'')};},
  async storage(){try{localStorage.setItem('__north_health','1');if(localStorage.getItem('__north_health')!=='1')throw new Error('写进去读不出来');localStorage.removeItem('__north_health');}catch(e){return{state:'bad',sub:'本机小存储不能用',why:'localStorage 写入失败：'+String(e&&e.message||e).slice(0,100),fix:'关掉无痕浏览；手机存储满了的话先清理空间。'};}
    try{const v='health-'+Date.now();await imgPut('__north_health_probe',v);const back=await imgGet('__north_health_probe');try{await imgDel('__north_health_probe');}catch(_){}if(back!==v)throw new Error('写进去读回来的不一样');}catch(e){return{state:'bad',sub:'聊天库不能读写',why:'聊天和图片存放的数据库读写失败：'+String(e&&e.message||e).slice(0,120),fix:'先别清数据，到「授权与数据」做一次备份，再彻底重开小手机；还不行截图发给维护的人。'};}
    let used='';try{if(healthPrivate()){const st=await window.SmallPhoneNative.request('storage.status');const total=+(st&&(st.totalBytes||st.deviceTotalBytes))||0,free=+(st&&(st.freeBytes||st.availableBytes||st.deviceFreeBytes))||0;if(total&&free){used=' · 手机剩余 '+healthMB(free);if(free<1073741824)return{state:'warn',sub:'聊天库可读写'+used,why:'手机只剩 '+healthMB(free)+' 空间，存聊天、图片和语音时可能失败。',fix:'清理手机空间，或到「授权与数据 → 查看占用明细」清掉不要的缓存。'};}}else if(navigator.storage&&navigator.storage.estimate){const e=await navigator.storage.estimate();if(e&&e.usage)used=' · 已用 '+healthMB(e.usage)+(e.quota?' / 可用 '+healthMB(e.quota):'');}}catch(_){}
    return{state:'ok',sub:'本机小存储和聊天库都能读写'+used};},
  async network(){if(navigator&&navigator.onLine===false)return{state:'bad',sub:'没有联网',why:'系统报告当前没有网络连接。',fix:'打开 Wi-Fi 或蜂窝数据后再检查。'};const url=healthPrivate()?'https://license.smallphoneapp.com/':(location.origin+location.pathname.replace(/[^/]*$/,'')+'sw.js?health='+Date.now()),t0=Date.now();try{await fetchT(url,{cache:'no-store',mode:healthPrivate()?'no-cors':'same-origin'},15000);return{state:'ok',sub:'已联网 · 访问小手机自己的服务器用时 '+healthSecs(Date.now()-t0)};}catch(e){return{state:'bad',sub:'连不上小手机自己的服务器',why:healthErr(e),fix:'检查网络；开着加速器的话换个节点或关掉再试。'};}},
  async chat(){const cfg=healthChatCfg(false);if(!cfg.base||!cfg.key||!cfg.model)return{state:'bad',sub:cfg.name+' · 还没填完整',why:'主模型的'+[!cfg.base&&'接口地址',!cfg.key&&'API Key',!cfg.model&&'模型名'].filter(Boolean).join('、')+'没填。',fix:'到「设置 → 网络连接 → 聊天模型」填好并保存。'};try{const r=await healthAsk(cfg,'只回一个字：在');if(r.fail)return{state:'bad',sub:cfg.name+' · '+cfg.model,why:r.fail,fix:'检查这条路线的地址、Key、模型名和余额；或在「聊天模型」里换一条路线。'};if(!r.text)return{state:'warn',sub:cfg.name+' · '+cfg.model+' · 用时 '+healthSecs(r.ms),why:'接口返回成功，但回复是空的（可能是思考模型把字都写进了思考里，或中转站过滤了内容）。',fix:'换一个非思考模型试试，或在「模型与路线诊断」里看原始回复。'};return{state:'ok',sub:cfg.name+' · '+cfg.model+' · 回复用时 '+healthSecs(r.ms)};}catch(e){return{state:'bad',sub:cfg.name+' · '+cfg.model,why:healthErr(e),fix:'检查网络和这条路线的地址；国外接口需要加速器。'};}},
  async aux(){const cfg=healthChatCfg(true);if(!cfg.model)return{state:'skip',sub:cfg.name+' · 没有设置副模型，这一项不检查'};if(!cfg.base||!cfg.key)return{state:'bad',sub:cfg.name+' · '+cfg.model,why:'副模型没有可用的接口地址或 Key（主模型那里也没填）。',fix:'到「设置 → 网络连接 → 辅助模型」填好。'};try{const r=await healthAsk(cfg,'只回一个字：在');if(r.fail)return{state:'bad',sub:cfg.name+' · '+cfg.model,why:r.fail,fix:'检查副模型的模型名和余额；副模型坏了时很多后台功能会改用主模型或失败。'};return{state:r.text?'ok':'warn',sub:cfg.name+' · '+cfg.model+' · 回复用时 '+healthSecs(r.ms),why:r.text?'':'接口返回成功，但回复是空的。',fix:r.text?'':'换一个非思考模型做副模型。'};}catch(e){return{state:'bad',sub:cfg.name+' · '+cfg.model,why:healthErr(e),fix:'检查网络和副模型地址。'};}},
