  async embed(){const cfg=healthChatCfg(false);if(!cfg.base||!cfg.key)return{state:'skip',sub:'聊天模型还没填完整，这一项不检查'};const tried=[];for(const model of ['text-embedding-3-small','text-embedding-ada-002','bge-m3']){const t0=Date.now();try{const r=await fetchT(cfg.base+'/embeddings',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+cfg.key},body:JSON.stringify({model,input:'她喜欢喝冰美式'})},20000);if(!r.ok){tried.push(model+'：'+(await healthHttpFail(r)).slice(0,60));continue;}const d=await r.json().catch(()=>null),v=d&&d.data&&d.data[0]&&d.data[0].embedding;if(!d.error&&Array.isArray(v)&&v.length>50&&v.every(x=>typeof x==='number'&&Number.isFinite(x))){try{S.settings._embedProbe={base:cfg.base,model,dims:v.length,at:Date.now()};save();}catch(_){}return{state:'ok',sub:cfg.name+' 支持 · '+model+' · '+v.length+' 维 · 用时 '+healthSecs(Date.now()-t0)};}tried.push(model+'：返回里没有可用的结果');}catch(e){tried.push(model+'：'+healthErr(e).slice(0,60));}}try{delete S.settings._embedProbe;save();}catch(_){}return{state:'skip',sub:cfg.name+' 不支持「算意思」 · 不影响聊天',why:'试了 '+tried.length+' 种：\n'+tried.join('\n'),fix:'现在找记忆用的是关键词加相近说法表，照常能用。想要更准的「按意思找记忆」，需要一条支持 embeddings 的接口。'};},
  async vision(){const v=S.settings.vision||{},own=!!(v.base&&v.key&&v.model),main=healthChatCfg(false),cfg=own?{base:String(v.base).replace(/\/+$/,''),key:v.key,model:v.model,name:'识图设置'}:main;if(!cfg.base||!cfg.key||!cfg.model)return{state:'skip',sub:'没有设置识图，也没有可用的聊天模型'};const img=typeof visionTestImage==='function'?visionTestImage():null;if(!img)return{state:'skip',sub:'这个浏览器画不出测试图，跳过'};const t0=Date.now();try{const r=await fetchT(cfg.base+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+cfg.key},body:JSON.stringify({model:cfg.model,max_tokens:40,messages:[{role:'user',content:[{type:'text',text:'图片中间有四位验证码，只回这四个字符。'},{type:'image_url',image_url:{url:img.dataURL}}]}]})},60000);const label=(own?'识图设置 · ':'用聊天模型 · ')+cfg.model;if(!r.ok)return{state:'bad',sub:label,why:await healthHttpFail(r),fix:own?'检查识图设置的地址、Key 和模型；或清空识图设置改用聊天模型。':'这个聊天模型可能不能看图；到「设置 → 识图」单独填一个能看图的模型。'};const result=await modelProbeResponse(r,60000),text=result.text.toUpperCase().replace(/[^A-Z0-9]/g,'');if(text===img.code)return{state:'ok',sub:label+' · 读出测试图里的验证码 · 用时 '+healthSecs(Date.now()-t0)};return{state:'warn',sub:label+' · 用时 '+healthSecs(Date.now()-t0),why:'能回话，但没认出测试图里的验证码「'+img.code+'」（它回的是「'+(text.slice(0,20)||'空')+'」），可能看不了图。',fix:'到「设置 → 识图」换一个能看图的模型。'};}catch(e){return{state:'bad',sub:(own?'识图设置 · ':'用聊天模型 · ')+cfg.model,why:healthErr(e),fix:'检查网络和识图接口地址。'};}},
  async image(){if(!S.settings.imgGen)return{state:'skip',sub:'没有开启 AI 真图，这一项不检查'};const ch=S.settings.chat||{},base=String(S.settings.imgBase||ch.base||'').replace(/\/+$/,''),key=S.settings.imgKey||ch.key||'',model=S.settings.imgModel||'gpt-image-2';if(!base||!key)return{state:'bad',sub:'AI 真图已开启，但没有接口',why:'生图的接口地址或 Key 没填（聊天模型那里也没有）。',fix:'到「设置 → 图片与识别 → AI 真图」填好路线。'};const t0=Date.now();try{const out=await imageGenerateExternal(base,key,model,'一只小猫坐在窗台上，真实照片','1024x1024','low',{timeoutMs:150000});if(!out||!out.url)return{state:'bad',sub:model,why:'接口返回了，但没有图片地址。',fix:'这个模型可能不支持生图，换一个生图模型。'};await modelProbeImage(out.url);return{state:'ok',sub:model+' · 出图用时 '+healthSecs(Date.now()-t0)};}catch(e){return{state:'bad',sub:model+' · 用时 '+healthSecs(Date.now()-t0),why:healthErr(e),fix:'检查生图路线的地址、Key、模型名和余额；也可以在「AI 真图」里换一条路线。'};}},
