async function healthRunOne(id){const item=HEALTH_ITEMS.find(x=>x.id===id);if(!item)return;if(!healthApplies(item)){_health.results[id]={state:'skip',sub:item.only==='web'?'这台是私人版，这一项只在网页版检查':'这一项只在私人版检查'};return;}_health.results[id]={state:'running',sub:'检查中…'};healthRefresh();const t0=Date.now(),limit=id==='image'?170000:id==='vision'||id==='search'?75000:60000;let res;try{res=await Promise.race([HEALTH_CHECKS[id](),new Promise(r=>setTimeout(()=>r({state:'bad',sub:'检查没有完成',why:Math.round(limit/1000)+' 秒还没有结果，检查超时。',fix:'稍后点「单独测」再试一次。'}),limit))]);}catch(e){res={state:'bad',sub:'检查出错',why:String(e&&e.message||e).slice(0,160),fix:'截图发给维护的人。'};}res=Object.assign({},res,{ms:Date.now()-t0});_health.results[id]=res;healthRefresh();}
