function healthReportText(){const lines=['小手机一键体检 · '+(typeof APP_VER!=='undefined'?APP_VER:'')+(healthPrivate()?' · 私人安装包 '+String(window.__SMALL_PHONE_PRIVATE_BUILD__||''):' · 网页版'),'检查时间：'+(_health.at?healthClock(_health.at,true):'还没检查')];let group='';for(const item of HEALTH_ITEMS){const r=_health.results[item.id];if(!r)continue;if(item.group!==group){group=item.group;lines.push('','【'+group+'】');}const tag={ok:'正常',warn:'需注意',bad:'未通过',skip:'跳过',running:'检查中'}[r.state]||r.state;lines.push('· '+item.title+'：'+tag+' — '+(r.sub||''));if(r.why)lines.push('  原因：'+r.why);if(r.fix)lines.push('  怎么办：'+r.fix);}return lines.join('\n');}
